// Runs once per resume. Turns the AI reply into one clean row for Google Sheets.
// Works with both Gemini and Claude replies.
// If anything goes wrong (API error, invalid JSON) we still output a row, flagged for manual review.
const res = $input.item.json;
const email = $('Gmail Trigger').item.json;

const receivedAt = email.date || new Date().toISOString();
const sender = (email.from && email.from.value && email.from.value[0]) || {};
const senderEmail = (sender.address || '').toLowerCase();
const senderName = sender.name || '';

// Fallback row: uses the sender's email so the duplicate check still works.
function fallback(reason) {
  return {
    json: {
      'Received At': receivedAt,
      'Name': senderName,
      'Email': senderEmail,
      'Phone': '',
      'Score': 0,
      'Recommendation': 'Maybe',
      'Summary': 'NEEDS MANUAL REVIEW\n' + String(reason).slice(0, 200) + '\nSubject: ' + (email.subject || ''),
      'Top Skills': '',
      'Missing Skills': '',
    }
  };
}

// 1. The HTTP node failed (timeout, bad key, rate limit, server error) and passed the error along.
if (res.error) {
  return fallback('AI API error: ' + (res.error.message || JSON.stringify(res.error)));
}

// 2. Get the reply text. Gemini and Claude put it in different places.
let text = '';
if (res.candidates) {
  // Gemini: candidates[0].content.parts[].text
  const candidate = res.candidates[0] || {};
  if (candidate.finishReason && candidate.finishReason !== 'STOP') {
    return fallback('Gemini stopped early: ' + candidate.finishReason);
  }
  const parts = (candidate.content && candidate.content.parts) || [];
  text = parts.map(part => part.text || '').join('');
} else if (res.content) {
  // Claude: content[] blocks, keep only the text ones
  if (res.stop_reason === 'refusal' || res.stop_reason === 'max_tokens') {
    return fallback('Claude stopped early: ' + res.stop_reason);
  }
  text = res.content.filter(block => block.type === 'text').map(block => block.text).join('');
} else if (res.promptFeedback && res.promptFeedback.blockReason) {
  return fallback('Gemini blocked the request: ' + res.promptFeedback.blockReason);
}

// 3. Parse the JSON. Strip ```json fences and any words around the {...} object.
let data;
try {
  const cleaned = text.replace(/```(?:json)?/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON object in reply');
  const jsonText = cleaned.slice(start, end + 1);
  try {
    data = JSON.parse(jsonText);
  } catch (firstErr) {
    // Second try: raw line breaks inside strings are invalid JSON, so turn them into spaces.
    data = JSON.parse(jsonText.replace(/[\r\n]+/g, ' '));
  }
} catch (err) {
  return fallback('Invalid JSON from AI: ' + err.message);
}

// 4. Validate and clean the fields.
let score = Math.round(Number(data.score));
if (!Number.isFinite(score)) score = 0;
score = Math.max(0, Math.min(100, score));

const allowed = ['Shortlist', 'Maybe', 'Reject'];
let recommendation = data.recommendation;
if (!allowed.includes(recommendation)) {
  recommendation = score >= 70 ? 'Shortlist' : score >= 45 ? 'Maybe' : 'Reject';
}

const list = value => Array.isArray(value) ? value.join(', ') : String(value || '');

return {
  json: {
    'Received At': receivedAt,
    'Name': data.name || senderName,
    'Email': String(data.email || senderEmail).trim().toLowerCase(),
    'Phone': data.phone || '',
    'Score': score,
    'Recommendation': recommendation,
    'Summary': data.summary || '',
    'Top Skills': list(data.top_skills),
    'Missing Skills': list(data.missing_skills),
  }
};
